const fs = require('fs');
const path = require('path');

const {
  AndroidConfig,
  withAndroidManifest,
  withAndroidStyles,
  withDangerousMod,
} = require('expo/config-plugins');

const TRANSPARENT_DRAWABLE = `<?xml version="1.0" encoding="utf-8"?>
<shape xmlns:android="http://schemas.android.com/apk/res/android" android:shape="rectangle">
  <solid android:color="#00000000" />
</shape>
`;

/**
 * Removes the native splash screen generated by the Expo template:
 * - points MainActivity at the regular app theme
 * - drops the Theme.App.SplashScreen style
 * - uses a transparent icon on Android 12+ so the system splash doesn't animate the app icon
 */
function withNoSplash(config) {
  config = withAndroidManifest(config, (cfg) => {
    const activity = AndroidConfig.Manifest.getMainActivityOrThrow(cfg.modResults);
    activity.$['android:theme'] = '@style/AppTheme';
    return cfg;
  });

  config = withAndroidStyles(config, (cfg) => {
    const resources = cfg.modResults.resources;
    resources.style = (resources.style ?? []).filter(
      (style) => style.$?.name !== 'Theme.App.SplashScreen'
    );

    const setStyleItem = (parentName, name, value) => {
      cfg.modResults = AndroidConfig.Styles.assignStylesValue(cfg.modResults, {
        add: true,
        parent: { name: parentName },
        name,
        value,
      });
    };

    setStyleItem(
      'AppTheme',
      'android:windowSplashScreenAnimatedIcon',
      '@drawable/splashscreen_transparent'
    );
    setStyleItem('AppTheme', 'android:windowSplashScreenBackground', '@android:color/transparent');

    return cfg;
  });

  return withDangerousMod(config, [
    'android',
    async (cfg) => {
      const resDir = path.join(cfg.modRequest.platformProjectRoot, 'app/src/main/res');
      const drawableDir = path.join(resDir, 'drawable');

      fs.mkdirSync(drawableDir, { recursive: true });
      fs.writeFileSync(path.join(drawableDir, 'splashscreen_transparent.xml'), TRANSPARENT_DRAWABLE);

      // The template's launcher background references the splash logo. Replace it
      // with a plain color so the splash images below can be removed safely.
      const launcherBackground = path.join(drawableDir, 'ic_launcher_background.xml');
      if (fs.existsSync(launcherBackground)) {
        fs.writeFileSync(
          launcherBackground,
          `<?xml version="1.0" encoding="utf-8"?>
<layer-list xmlns:android="http://schemas.android.com/apk/res/android">
  <item android:drawable="@color/splashscreen_background"/>
</layer-list>
`
        );
      }

      // Delete the splash logo images generated from the app icon.
      for (const entry of fs.readdirSync(resDir)) {
        if (!entry.startsWith('drawable')) {
          continue;
        }
        const logo = path.join(resDir, entry, 'splashscreen_logo.png');
        if (fs.existsSync(logo)) {
          fs.rmSync(logo);
        }
      }

      return cfg;
    },
  ]);
}

module.exports = withNoSplash;
